<?php
declare(strict_types=1);session_start();date_default_timezone_set('Asia/Tehran');
if(!file_exists(__DIR__.'/config.php')){header('Location:install.php');exit;}$c=require __DIR__.'/config.php';
try{$pdo=new PDO('mysql:host='.$c['db_host'].';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);require_once __DIR__.'/schema.php';ensure_product_schema($pdo);}catch(Throwable $e){exit('اتصال برقرار نیست.');}
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function toman($n){return number_format((int)$n).' تومان';}
$orderId=max(0,(int)($_REQUEST['order']??($_SESSION['last_order_id']??0)));$phone=trim((string)($_REQUEST['phone']??($_SESSION['last_phone']??'')));$order=null;$items=[];$error='';
if($orderId>0&&$phone!==''){$st=$pdo->prepare('SELECT o.*,c.name customer_name,c.phone,c.address FROM orders o JOIN customers c ON c.id=o.customer_id WHERE o.id=? AND c.phone=? LIMIT 1');$st->execute([$orderId,$phone]);$order=$st->fetch();if($order){$q=$pdo->prepare('SELECT oi.*,p.image_path FROM order_items oi LEFT JOIN products p ON p.id=oi.product_id WHERE oi.order_id=? ORDER BY oi.id');$q->execute([$orderId]);$items=$q->fetchAll();$_SESSION['last_order_id']=$orderId;$_SESSION['last_phone']=$phone;}else$error='سفارشی با این شماره و موبایل پیدا نشد.';}
$labels=['new'=>'ثبت شد','confirmed'=>'تأیید شد','preparing'=>'در حال جمع‌آوری','ready'=>'آماده ارسال','out'=>'در مسیر','delivered'=>'تحویل شد'];$flow=array_keys($labels);$current=$order?array_search($order['status'],$flow,true):false;
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#11823b"><title>پیگیری سفارش | سوپرمارکت طهران</title><link rel="stylesheet" href="assets/style.css?v=20261024-track"><style>.track-wrap{max-width:720px;margin:24px auto;padding:0 15px}.track-card{background:#fff;border:1px solid #e7eee8;border-radius:18px;padding:16px;margin-bottom:14px}.timeline{display:grid;grid-template-columns:repeat(6,1fr);gap:6px;margin:18px 0}.step{font-size:10px;text-align:center;color:#859087}.step i{display:block;width:24px;height:24px;border-radius:50%;margin:0 auto 6px;background:#e8eee9}.step.done{color:#11823b;font-weight:700}.step.done i{background:#11823b}.track-item{display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid #eef1ee}.track-item img{width:56px;height:56px;object-fit:contain;border-radius:10px}.track-item .grow{flex:1}.lookup{display:grid;grid-template-columns:1fr 1fr auto;gap:8px}@media(max-width:650px){.timeline{grid-template-columns:repeat(3,1fr);row-gap:14px}.lookup{grid-template-columns:1fr}.track-wrap{margin-top:12px}}</style></head><body><header class="top"><a class="brand" href="index.php"><span class="logo">📦</span><span><b>پیگیری سفارش</b><small>سوپرمارکت طهران</small></span></a><a class="btn pale" href="index.php">ادامه خرید</a></header><main class="track-wrap"><div class="track-card"><h2>سفارشت کجاست؟</h2><form class="lookup" method="get"><input name="order" inputmode="numeric" placeholder="شماره سفارش" value="<?=$orderId?:''?>" required><input name="phone" inputmode="numeric" placeholder="شماره موبایل" value="<?=e($phone)?>" required><button class="btn">پیگیری</button></form><?php if($error):?><div class="notice"><?=e($error)?></div><?php endif;?></div><?php if($order):?><div class="track-card"><div class="sectionhead"><div><h2>سفارش #<?=(int)$order['id']?></h2><p><?=e($order['created_at'])?></p></div><b><?=toman($order['total'])?></b></div><?php if($order['status']==='cancelled'):?><div class="notice">این سفارش لغو شده و موجودی کالاها به فروشگاه برگشته است.</div><?php else:?><div class="timeline"><?php foreach($labels as $k=>$v):$ix=array_search($k,$flow,true);?><div class="step <?=($current!==false&&$ix<=$current)?'done':''?>"><i></i><?=e($v)?></div><?php endforeach;?></div><?php endif;?><p><b>تحویل:</b> <?=e($order['delivery_slot'])?></p><p><b>آدرس:</b> <?=e($order['address'])?></p></div><div class="track-card"><h3>کالاهای سفارش</h3><?php foreach($items as $it):?><div class="track-item"><?php if(!empty($it['image_path'])):?><img src="<?=e($it['image_path'])?>" alt=""><?php endif;?><div class="grow"><b><?=e($it['product_name'])?></b><div class="muted"><?=number_format((int)$it['quantity'])?> عدد · <?=toman((int)$it['unit_price'])?></div></div><strong><?=toman((int)$it['unit_price']*(int)$it['quantity'])?></strong></div><?php endforeach;?></div><?php endif;?></main></body></html>
